export function draftToolsHTML({key,inputId}){return `<p class="small muted">Gemini feedback is for adult learners. Before submitting, remove names, contact details, and other personal or confidential information. Google may use free-tier writing and responses for product improvement and human review.</p><section class="writing-draft-tools" data-writing-tools="${esc(key)}"><p class="small" role="status" data-writing-save-status="${esc(key)}">${esc(statusText(key))}</p><div class="button-row"><button type="button" class="button secondary" data-writing-action="save" data-writing-key="${esc(key)}" data-writing-input="${esc(inputId)}">Save draft now</button><button type="button" class="button secondary" data-writing-action="recover" data-writing-key="${esc(key)}" data-writing-input="${esc(inputId)}">Recover saved drafts</button><button type="button" class="button secondary" data-writing-action="download" data-writing-key="${esc(key)}" data-writing-input="${esc(inputId)}">Download draft</button></div><div data-writing-recovery="${esc(key)}"></div><p class="small muted">Autosave keeps your response and plan separate from submitted homework. Reopen this activity with the same account. Device drafts survive refreshes and app updates; account backups become available after a successful sync. If browser data is cleared before sync, unsynced work cannot be recovered.</p></section>`;}
export function flushWritingDrafts(){return flush({force:true});}
async function flush({keepalive=false,force=false}={}){
 sync();if(owner==='guest'||options.isTeacher?.())return;const user=owner;
 for(const key of [...dirty]){if(busy.has(key)&&force)try{await writingFlights.get(key);}catch{}if(busy.has(key)||!keepalive&&!force&&Date.now()-(lastSent.get(key)||0)<15000)continue;if(!keepalive)await hydrateWriting(key);if(user!==sync())return;const r=read(key);if(!r||!hasWriting(r)&&!hydrated.has(user+':'+key))continue;busy.add(key);lastSent.set(key,Date.now());
  try{const flight=options.request('/api/student/writing-drafts',{method:'POST',keepalive,body:JSON.stringify({key,deviceId:device,revision:r.revision,text:r.text,plan:r.plan})});writingFlights.set(key,flight);const result=await flight;if(user!==sync())continue;if(result.revision!==r.revision)throw new Error('A newer backup is available.');statuses.set(key,{...statuses.get(key),cloud:r.revision,cloudError:''});if(read(key)?.revision===r.revision)dirty.delete(key);}
  catch(e){if(user===sync())statuses.set(key,{...statuses.get(key),cloudError:e.message});}
  finally{busy.delete(key);writingFlights.delete(key);if(user===owner)paintStatus(key);}
 }
}
function ownInput(key,inputId){const n=document.getElementById(inputId);return n?.dataset.writingDraftKey===key?n:null;}
function recoveryNode(key){return [...document.querySelectorAll('[data-writing-recovery]')].find(n=>n.dataset.writingRecovery===key);}
function recoveryHTML(key,inputId,list,error=''){return `<h4>Choose a saved copy</h4><p class="small">Preview before restoring. Your current writing is saved as a recovery copy first.</p>${error?`<p class="notice warm">${esc(error)} Local copies are still available.</p>`:''}${list.map((r,i)=>`<details><summary>${esc(r.label)} · ${count(r.text)} words</summary><pre class="writing-recovery-preview">${esc(r.text||'(Empty response)')}</pre><p class="small">Plan: ${esc(Object.values(r.plan||{}).filter(v=>typeof v==='string').join(' · ').slice(0,700))}</p><button type="button" class="button soft" data-writing-action="restore" data-writing-key="${esc(key)}" data-writing-input="${esc(inputId)}" data-writing-copy="${i}">Restore this copy</button></details>`).join('')||'<p>No earlier copy is available yet. Start writing to create a saved draft.</p>'}`;}
export function initWritingStudio(callbacks){
 options=callbacks;sync();try{device=options.storage.getItem(DEVICE)||crypto.randomUUID();options.storage.setItem(DEVICE,device);}catch{device=crypto.randomUUID();}
 // Clipboard and drag/drop guards work without reading the clipboard. IME composition and normal typing stay available.
 const responseBox=n=>n?.id!=='teacherFeedback'&&n?.matches?.('#essay,[data-draft],[data-mock-draft],[data-course-text="text"],[data-course-text="task1"],[data-course-text="task2"],[data-coach-revision]');
 const block=e=>{e.preventDefault();options.toast?.('Please type your own answer. Pasting and dragging text into the writing box are disabled.');};
 document.addEventListener('paste',e=>{if(responseBox(e.target))block(e);},true);
 document.addEventListener('drop',e=>{if(responseBox(e.target))block(e);},true);
 document.addEventListener('dragover',e=>{if(responseBox(e.target))e.preventDefault();},true);
 document.addEventListener('beforeinput',e=>{if(responseBox(e.target)&&/^(insertFromPaste|insertFromDrop)/.test(e.inputType||''))block(e);},true);
 document.addEventListener('keydown',e=>{if(responseBox(e.target)&&((e.ctrlKey||e.metaKey)&&e.key?.toLowerCase()==='v'||e.shiftKey&&e.key==='Insert'))block(e);},true);
 document.addEventListener('input',e=>{const n=e.target,key=n.dataset.writingDraftKey||n.dataset.writingKey;if(!key)return;if(n.dataset.writingDraftKey){captureWritingDraft(key,n.value);}else if(n.dataset.writingPlan){const r=read(key);save(key,r?.text||'',{...r?.plan,[n.dataset.writingPlan]:n.value});}},true);
 document.addEventListener('change',e=>{const n=e.target,key=n.dataset.writingKey||n.dataset.writingFormat;if(!key)return;const r=read(key);if(n.dataset.writingFormat){save(key,r?.text||'',{...r?.plan,format:n.value},true);options.render?.();}else if(n.dataset.writingCheck!==undefined)save(key,r?.text||'',{...r?.plan,['check'+n.dataset.writingCheck]:n.checked});});
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-writing-action]');if(!b)return;const key=b.dataset.writingKey,inputId=b.dataset.writingInput,n=ownInput(key,inputId);if(!n)return;const action=b.dataset.writingAction,user=sync();
  if(action==='save'){save(key,n.value,read(key)?.plan,true);lastSent.delete(key);void flush({force:true});options.toast?.(statuses.get(key)?.local===false?statuses.get(key).error:'Draft saved. Check the save status for account backup.');}
  if(action==='download'){save(key,n.value,read(key)?.plan,true);const r=read(key),text='Richmount IELTS writing draft\nSaved: '+r.updatedAt+'\nActivity: '+key+'\n\nPLAN\n'+Object.entries(r.plan).filter(([k])=>!k.startsWith('check')).map(([k,v])=>k+': '+v).join('\n')+'\n\nRESPONSE\n'+r.text;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Richmount-Writing-Draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  if(action==='recover'){try{const raw=JSON.parse(options.storage.getItem(storageKey(key))||'null');if(validRecord(raw,key)&&raw.revision!==read(key)?.revision)externalCopies.set(key,[{...raw,label:'Another saved device copy · '+raw.updatedAt}]);}catch{}save(key,n.value,read(key)?.plan,true);const r=read(key),list=[{...r,label:'Latest copy on this device · '+r.updatedAt},...(r.snapshots||[]).map(v=>({...v,label:'Earlier device copy · '+v.updatedAt})),...(externalCopies.get(key)||[])];recoveries.set(key,list);const node=recoveryNode(key);if(node)node.innerHTML=recoveryHTML(key,inputId,list);if(user==='guest')return;
   try{const data=await options.request('/api/student/writing-drafts?key='+encodeURIComponent(key));if(user!==sync())return;for(const d of data.drafts||[]){list.push({...d,label:'Account backup · '+d.updatedAt});if(d.previous)list.push({...d.previous,label:'Previous account copy · '+d.previous.updatedAt});}if(node&&node.isConnected!==false)node.innerHTML=recoveryHTML(key,inputId,list);}
   catch(error){if(user===sync()&&node&&node.isConnected!==false)node.innerHTML=recoveryHTML(key,inputId,list,error.message);}
  }
  if(action==='restore'){const copy=recoveries.get(key)?.[Number(b.dataset.writingCopy)];if(!copy)return;save(key,n.value,read(key)?.plan,true);save(key,copy.text,copy.plan,true);n.value=copy.text;n.dispatchEvent(new Event('input',{bubbles:true}));options.render?.();options.toast?.('Saved copy restored. Your previous writing is kept in recovery.');}
 });
 const checkpoint=()=>{document.querySelectorAll('[data-writing-draft-key]').forEach(n=>save(n.dataset.writingDraftKey,n.value,read(n.dataset.writingDraftKey)?.plan,true));};
 window.addEventListener('pagehide',()=>{checkpoint();void flush({keepalive:true});});window.addEventListener('beforeunload',checkpoint);window.addEventListener('online',()=>{lastSent.clear();void flush();});document.addEventListener('visibilitychange',()=>{if(document.hidden){checkpoint();void flush({keepalive:true,force:true});}else void flush();});
 window.addEventListener('storage',e=>{if(e.key?.startsWith(PREFIX)){for(const key of records.keys())if(e.key===storageKey(key)){const n=[...document.querySelectorAll('[data-writing-draft-key]')].find(n=>n.dataset.writingDraftKey===key);if(n){try{const copy=JSON.parse(e.newValue);if(validRecord(copy,key))externalCopies.set(key,[{...copy,label:'Copy saved by another tab · '+copy.updatedAt},...(externalCopies.get(key)||[])].slice(0,4));}catch{}options.toast?.('Another tab saved this activity. Use Recover saved drafts to inspect copies before continuing.');}else records.delete(key);}}});
 setInterval(()=>void flush(),15000);
}
